actions.script:
function isValueText(t){return /^[\d][\d.,]*\s?[KMB]?$/.test(t);}
function findMetricInModal(modal,labelText){var all=[].slice.call(modal.querySelectorAll('*'));for(var i=0;i<all.length;i++){var el=all[i];if(el.children.length===0&&el.textContent.trim()===labelText){var container=el.parentElement;for(var t=0;t<8;t++){if(!container||container===modal||container===document.body)break;var cands=[].slice.call(container.querySelectorAll('span,div,p,h1,h2,h3')).filter(function(e){var txt=e.textContent.trim();return e.children.length===0&&txt!==labelText&&isValueText(txt);});if(cands.length>0)return cands[0].textContent.trim();container=container.parentElement;}}}return null;}
function findDofollowInModal(modal,labelText){var all=[].slice.call(modal.querySelectorAll('*'));for(var i=0;i<all.length;i++){var el=all[i];if(el.children.length===0&&el.textContent.trim()===labelText){var container=el.parentElement;for(var t=0;t<8;t++){if(!container||container===modal||container===document.body)break;var cands=[].slice.call(container.querySelectorAll('*')).filter(function(e){return e.children.length===0&&/(\d+)%\s*dofollow/i.test(e.textContent);});if(cands.length>0){var m=cands[0].textContent.match(/(\d+)%/);return m?m[1]:null;}container=container.parentElement;}}}return null;}
function authorityModalReady(modal){return !!modal&&modal.textContent.indexOf('Domain Rating')!==-1&&findMetricInModal(modal,'Domain Rating')!==null;}
function hasTurnstileIframe(){var iframes=document.querySelectorAll('iframe');for(var i=0;i<iframes.length;i++){if(iframes[i].src&&iframes[i].src.indexOf('challenges.cloudflare.com')!==-1)return true;}return false;}
async function requestTurnstileFocus(){return new Promise(function(resolve){var timeout=setTimeout(function(){window.removeEventListener('message',handler);resolve({success:false,reason:'timeout'});},40000);function handler(event){if(event.source===window&&event.data&&event.data.type==='TURNSTILE_FOCUS_RESPONSE'){clearTimeout(timeout);window.removeEventListener('message',handler);resolve(event.data);}}window.addEventListener('message',handler);window.postMessage({type:'TURNSTILE_FOCUS_REQUEST'},'*');});}
async function waitForModalWithFocusQueue(maxRetries){for(var attempt=0;attempt<maxRetries;attempt++){var modal=null;var startTime=Date.now();var focusRequested=false;var modalTimeout=40000;await new Promise(function(r){setTimeout(r,2000);});if(hasTurnstileIframe()&&!focusRequested){focusRequested=true;var focusResult=await requestTurnstileFocus();if(focusResult.reason==='modal_appeared'||focusResult.reason==='solved'||focusResult.reason==='no_turnstile'){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(authorityModalReady(modal)){return{success:true,modal:modal,attempts:attempt+1};}}}while(Date.now()-startTime<modalTimeout){modal=document.querySelector('.ReactModalPortal [role="dialog"]')||document.querySelector('[class*="ReactModal__Content"]');if(authorityModalReady(modal)){return{success:true,modal:modal,attempts:attempt+1};}if(hasTurnstileIframe()&&!focusRequested&&Date.now()-startTime>5000){focusRequested=true;var focusResult=await requestTurnstileFocus();}await new Promise(function(r){setTimeout(r,500);});}if(attempt<maxRetries-1){window.location.reload();await new Promise(function(r){setTimeout(r,5000);});}}return{success:false,error:'modal timeout after '+maxRetries+' attempts',attempts:maxRetries};}
var currentDomain='${domains}'.split(',')[0].trim();var allResults=[];var waitResult=await waitForModalWithFocusQueue(3);if(!waitResult.success){allResults.push({domain_name:currentDomain,error:waitResult.error,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});}var modal=waitResult.modal;await new Promise(function(r){setTimeout(r,3000)});var dr=null,backlinks=null,linking_websites=null;var settleDeadline=Date.now()+12000;while(true){dr=findMetricInModal(modal,'Domain Rating');backlinks=findMetricInModal(modal,'Backlinks');linking_websites=findMetricInModal(modal,'Linking websites');var loaded=backlinks!==null&&linking_websites!==null&&!(backlinks==='0'&&linking_websites==='0');if(loaded||Date.now()>settleDeadline)break;await new Promise(function(r){setTimeout(r,1000)});}var bl_df=findDofollowInModal(modal,'Backlinks');var lw_df=findDofollowInModal(modal,'Linking websites');allResults.push({domain_name:currentDomain,dr:dr,backlinks:backlinks,backlinks_dofollow_percentage:bl_df,linking_websites:linking_websites,linking_websites_dofollow_percentage:lw_df,turnstile_retries:waitResult.attempts});return JSON.stringify({total_domains:1,results:allResults});
